//! EPUB package + TOC parity against oracle stage dumps.
//!
//! Fixtures: `tests/fixtures/epub/*.epub` with `*.package.json` oracle dumps
//! (generated by `tests/golden/epub_fixtures.py`).

use std::fs::File;
use std::path::PathBuf;
use wenyi_core::document::epub;
use zip::ZipArchive;

fn fixture(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("epub")
        .join(name)
}

fn load_json(name: &str) -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(fixture(name)).unwrap()).unwrap()
}

#[test]
fn package_matches_oracle() {
    for name in [
        "sample",
        "nested_toc",
        "grouped_nav",
        "cross_resource",
        "degenerate",
    ] {
        let file = File::open(fixture(&format!("{name}.epub"))).unwrap();
        let mut archive = ZipArchive::new(file).unwrap();
        let opf_path = epub::find_opf_path(&mut archive).unwrap();
        let package = epub::parse_opf(&mut archive, &opf_path).unwrap();
        let want = load_json(&format!("{name}.package.json"));
        assert_eq!(opf_path, want["opf_path"].as_str().unwrap(), "{name}");
        assert_eq!(package.title, want["title"].as_str().unwrap(), "{name}");
        let got: Vec<&str> = package.spine_hrefs.iter().map(String::as_str).collect();
        let want_refs: Vec<&str> = want["spine_hrefs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(got, want_refs, "{name} spine");
        let got: Vec<&str> = package.toc_paths.iter().map(String::as_str).collect();
        let want_refs: Vec<&str> = want["toc_paths"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(got, want_refs, "{name} toc_paths");
        let got: Vec<&str> = package
            .manifest_xhtml_hrefs
            .iter()
            .map(String::as_str)
            .collect();
        let want_refs: Vec<&str> = want["manifest_xhtml_hrefs"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(got, want_refs, "{name} manifest");
    }
}

#[test]
fn toc_entries_match_oracle() {
    for name in [
        "sample",
        "nested_toc",
        "grouped_nav",
        "cross_resource",
        "degenerate",
    ] {
        let file = File::open(fixture(&format!("{name}.epub"))).unwrap();
        let mut archive = ZipArchive::new(file).unwrap();
        let opf_path = epub::find_opf_path(&mut archive).unwrap();
        let package = epub::parse_opf(&mut archive, &opf_path).unwrap();
        let entries = epub::parse_toc_entries(&mut archive, &package.toc_paths);
        let got = serde_json::to_value(&entries).unwrap();
        assert_eq!(got, want_entries(name), "{name} toc entries");
    }
}

fn want_entries(name: &str) -> serde_json::Value {
    load_json(&format!("{name}.package.json"))["toc_entries"].clone()
}
